def transform_v2(grid):
    h,w=len(grid),len(grid[0])
    points=[(r,c,grid[r][c]) for r in range(h) for c in range(w) if grid[r][c]!=0]
    if len(points)==h*w:
        return [row[:] for row in grid]
    feats=[lambda r,c:r,lambda r,c:c,lambda r,c:r+c,lambda r,c:c-r]
    grouped=[];scores=[]
    for f in feats:
        groups=defaultdict(list)
        for r,c,v in points:groups[f(r,c)].append(v)
        grouped.append(groups)
        scores.append(sum(len(vs) for vs in groups.values() if len(vs)>=2 and len(set(vs))==1))
    idx=max(range(len(feats)),key=lambda j:scores[j])
    f=feats[idx]; groups=grouped[idx]
    period=len(groups)
    def build(p0):
        mapping={}
        for r,c,v in points:
            residue=f(r,c)%p0
            if residue in mapping and mapping[residue]!=v:
                return None
            mapping[residue]=v
        return mapping
    mapping=build(period)
    if mapping is None:
        for period in range(period+1,2*max(h,w)+1):
            mapping=build(period)
            if mapping is not None:break
    background=Counter(v for _,_,v in points).most_common(1)[0][0]
    return [[mapping.get(f(r,c)%period,background) for c in range(w)] for r in range(h)]

